package writ

import (
	"encoding/json"
	"errors"
	"net/http"
	"net/http/httptest"
	"testing"
)

// (a) Every verb routes to the real /api/targets path and method, and unset
// query params are omitted — "?limit=" is not the same as no limit, and the API
// rejects the empty string for a typed int.
func TestCloudMonitorsRouting(t *testing.T) {
	clearCloudEnv(t)
	type call struct{ method, path, query string }
	var calls []call
	var createBody map[string]any
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls = append(calls, call{r.Method, r.URL.Path, r.URL.RawQuery})
		if r.Method == http.MethodPost && r.URL.Path == "/api/targets" {
			_ = json.NewDecoder(r.Body).Decode(&createBody)
		}
		if r.Method == http.MethodDelete {
			w.WriteHeader(http.StatusNoContent)
			return
		}
		switch r.URL.Path {
		case "/api/targets":
			if r.Method == http.MethodGet {
				_, _ = w.Write([]byte(`[{"id":412,"url":"https://example.com/pricing","checkType":"content","checkPeriodMs":300000,"enabled":true}]`))
				return
			}
		// The two change routes answer DIFFERENT shapes and must be mocked
		// separately. Serving one camelCase body for both is what hid a shipped
		// bug: the global feed's numeric `id` cannot decode into a Go string, so
		// RecentChanges failed against every real response while the tests passed.
		case "/api/targets/412/changes":
			_, _ = w.Write([]byte(`[{"id":"9","targetId":"412","timestamp":"2026-08-05T00:00:00Z",` +
				`"firstDetectedAt":"2026-08-05T00:00:00Z","lastDetectedAt":"2026-08-05T00:01:00Z",` +
				`"oldContent":"$1,199","newContent":"$1,099","diff":"-+","detectedBy":"1 agent"}]`))
			return
		case "/api/targets/changes/recent":
			// Verbatim RecentChangeInfo (backend/routers/targets.py): snake_case,
			// integer ids, diff_snippet, both detection timestamps.
			_, _ = w.Write([]byte(`[{"id":9,"target_id":412,"target_url":"https://example.com/pricing",` +
				`"target_selector_id":null,"selector_name":null,"diff_snippet":"-$1,199 +$1,099",` +
				`"first_detected_at":"2026-08-05T00:00:00+00:00","last_detected_at":"2026-08-05T00:01:00+00:00"}]`))
			return
		case "/api/targets/412/run":
			_, _ = w.Write([]byte(`{"ok":true,"dispatched":2}`))
			return
		}
		_, _ = w.Write([]byte(`{"id":412,"url":"https://example.com/pricing","checkType":"content","checkPeriodMs":300000,"enabled":true,"changesCount":0}`))
	}))
	defer srv.Close()

	c := New(WithCloudURL(srv.URL), WithAPIKey("wt_test"))
	ctx := ctxT(t)
	period := int64(300000)

	mon, err := c.Cloud.Monitors.Create(ctx, CloudMonitorParams{
		URL: "https://example.com/pricing", CheckType: "content",
		Selector: strPtr(".price"), CheckPeriodMs: &period,
	})
	if err != nil {
		t.Fatal(err)
	}
	// The cloud ACCEPTS snake_case and ANSWERS camelCase — assert both halves.
	if createBody["check_period_ms"] != float64(300000) || createBody["selector"] != ".price" {
		t.Errorf("create body = %+v", createBody)
	}
	if mon.CheckPeriodMs == nil || *mon.CheckPeriodMs != 300000 {
		t.Errorf("monitor = %+v", mon)
	}

	if _, err := c.Cloud.Monitors.List(ctx, nil); err != nil {
		t.Fatal(err)
	}
	limit := 50
	if _, err := c.Cloud.Monitors.List(ctx, &CloudMonitorListOptions{EnabledOnly: true, Limit: &limit}); err != nil {
		t.Fatal(err)
	}
	if _, err := c.Cloud.Monitors.Get(ctx, 412); err != nil {
		t.Fatal(err)
	}
	if _, err := c.Cloud.Monitors.Update(ctx, 412, CloudMonitorParams{CheckPeriodMs: &period}); err != nil {
		t.Fatal(err)
	}
	if _, err := c.Cloud.Monitors.Toggle(ctx, 412, false); err != nil {
		t.Fatal(err)
	}
	run, err := c.Cloud.Monitors.Run(ctx, 412)
	if err != nil {
		t.Fatal(err)
	}
	if !run.OK || run.Dispatched != 2 {
		t.Errorf("run = %+v", run)
	}
	changes, err := c.Cloud.Monitors.Changes(ctx, 412, &CloudChangeListOptions{Limit: &limit})
	if err != nil {
		t.Fatal(err)
	}
	if len(changes) != 1 || changes[0].NewContent != "$1,099" {
		t.Errorf("changes = %+v", changes)
	}
	if changes[0].LastDetectedAt != "2026-08-05T00:01:00Z" {
		t.Errorf("per-monitor change must expose the field the feed is ORDERED by: %+v", changes[0])
	}
	recent, err := c.Cloud.Monitors.RecentChanges(ctx, nil)
	if err != nil {
		t.Fatal(err)
	}
	// The regression this guards: every field below decoded as a zero value (or
	// failed outright) while the global feed shared the per-monitor type.
	if len(recent) != 1 {
		t.Fatalf("recent = %+v", recent)
	}
	if recent[0].ID != 9 || recent[0].TargetID != 412 {
		t.Errorf("recent ids must decode as integers: %+v", recent[0])
	}
	if recent[0].TargetURL != "https://example.com/pricing" {
		t.Errorf("recent target_url = %q", recent[0].TargetURL)
	}
	if recent[0].DiffSnippet == nil || *recent[0].DiffSnippet != "-$1,199 +$1,099" {
		t.Errorf("recent diff_snippet = %+v", recent[0].DiffSnippet)
	}
	if recent[0].LastDetectedAt != "2026-08-05T00:01:00+00:00" {
		t.Errorf("recent last_detected_at = %q (the cursor field)", recent[0].LastDetectedAt)
	}
	if err := c.Cloud.Monitors.Delete(ctx, 412); err != nil {
		t.Fatal(err)
	}

	want := []call{
		{"POST", "/api/targets", ""},
		{"GET", "/api/targets", ""},
		{"GET", "/api/targets", "enabled_only=true&limit=50"},
		{"GET", "/api/targets/412", ""},
		{"PATCH", "/api/targets/412", ""},
		{"PATCH", "/api/targets/412/toggle", "enabled=false"},
		{"POST", "/api/targets/412/run", ""},
		{"GET", "/api/targets/412/changes", "limit=50"},
		{"GET", "/api/targets/changes/recent", ""},
		{"DELETE", "/api/targets/412", ""},
	}
	if len(calls) != len(want) {
		t.Fatalf("made %d calls, want %d: %+v", len(calls), len(want), calls)
	}
	for i, w := range want {
		if calls[i] != w {
			t.Errorf("call %d = %+v, want %+v", i, calls[i], w)
		}
	}
}

// (b) The keyless tier has no account to own a monitor, so every verb fails
// BEFORE any network call rather than on a 401 the caller cannot act on.
func TestCloudMonitorsKeylessRefusesBeforeRequest(t *testing.T) {
	clearCloudEnv(t)
	var hits int
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		hits++
		_, _ = w.Write([]byte(`{}`))
	}))
	defer srv.Close()

	c := New(WithCloudURL(srv.URL), WithClientID("dev-123"))
	ctx := ctxT(t)
	m := c.Cloud.Monitors

	_, errList := m.List(ctx, nil)
	_, errCreate := m.Create(ctx, CloudMonitorParams{URL: "https://x.test"})
	_, errGet := m.Get(ctx, 1)
	_, errUpdate := m.Update(ctx, 1, CloudMonitorParams{})
	_, errToggle := m.Toggle(ctx, 1, true)
	_, errRun := m.Run(ctx, 1)
	_, errChanges := m.Changes(ctx, 1, nil)
	_, errRecent := m.RecentChanges(ctx, nil)
	errDelete := m.Delete(ctx, 1)

	for name, err := range map[string]error{
		"List": errList, "Create": errCreate, "Get": errGet, "Update": errUpdate,
		"Toggle": errToggle, "Run": errRun, "Changes": errChanges,
		"RecentChanges": errRecent, "Delete": errDelete,
	} {
		var want *APIKeyRequiredError
		if !errors.As(err, &want) {
			t.Errorf("%s error = %v, want *APIKeyRequiredError", name, err)
		}
	}
	if hits != 0 {
		t.Errorf("made %d network calls, want 0", hits)
	}
}

func strPtr(s string) *string { return &s }

package writ

import (
	"errors"
	"os"
	"testing"
)

// Env-gated LIVE test: drives client.Cloud.Monitors and client.Cloud.Crawl
// against a REAL running coordinator. No stub server — this is the test that
// would catch a wrong path, a wrong JSON casing, or a scope the route map never
// mapped.
//
//	WRIT_E2E=1 WRIT_CLOUD_URL=http://localhost:8000 WRIT_API_KEY=wt_… go test -run Live -v ./...
//
// The key needs monitors:read/write/execute/delete and crawl:read/execute.
// Skipped (not failed) when WRIT_E2E is unset so `go test ./...` stays hermetic.
func TestCloudMonitorsLive(t *testing.T) {
	if os.Getenv("WRIT_E2E") != "1" {
		t.Skip("set WRIT_E2E=1 (plus WRIT_CLOUD_URL/WRIT_API_KEY) to run against a live coordinator")
	}
	// example.com is the one seed guaranteed to answer 200 — the API fetches the
	// page to establish a baseline, so a 404 seed is rejected outright.
	const seed = "https://example.com"

	c := New(
		WithCloudURL(envOr("WRIT_CLOUD_URL", "http://localhost:8000")),
		WithAPIKey(os.Getenv("WRIT_API_KEY")),
	)
	if c.Cloud.Tier() != TierMetered {
		t.Fatalf("tier = %q, want metered (is WRIT_API_KEY set?)", c.Cloud.Tier())
	}
	ctx := ctxT(t)
	m := c.Cloud.Monitors

	period := int64(300000)
	mon, err := m.Create(ctx, CloudMonitorParams{
		URL: seed, CheckType: "content",
		Selector: strPtr("h1"), CheckPeriodMs: &period,
	})
	if err != nil {
		t.Fatalf("create: %v", err)
	}
	// Never leave a monitor behind, even if an assertion below fails.
	defer func() { _ = m.Delete(ctx, mon.ID) }()

	// The struct tags in cloud_monitors.go claim camelCase — assert the server agrees.
	if mon.CheckPeriodMs == nil || *mon.CheckPeriodMs != 300000 {
		t.Errorf("checkPeriodMs = %v, want 300000", mon.CheckPeriodMs)
	}
	if mon.Selector == nil || *mon.Selector != "h1" {
		t.Errorf("selector = %v, want h1", mon.Selector)
	}
	if !mon.Enabled {
		t.Error("a new monitor should be enabled")
	}

	limit := 100
	listed, err := m.List(ctx, &CloudMonitorListOptions{Limit: &limit})
	if err != nil {
		t.Fatalf("list: %v", err)
	}
	if !containsMonitor(listed, mon.ID) {
		t.Errorf("list did not contain the monitor just created (%d rows)", len(listed))
	}

	got, err := m.Get(ctx, mon.ID)
	if err != nil || got.URL != seed {
		t.Fatalf("get: %v (url=%q)", err, got.URL)
	}

	slower := int64(600000)
	upd, err := m.Update(ctx, mon.ID, CloudMonitorParams{CheckPeriodMs: &slower})
	if err != nil || upd.CheckPeriodMs == nil || *upd.CheckPeriodMs != 600000 {
		t.Fatalf("update: %v (period=%v)", err, upd.CheckPeriodMs)
	}

	off, err := m.Toggle(ctx, mon.ID, false)
	if err != nil || off.Enabled {
		t.Fatalf("toggle(false): %v (enabled=%v)", err, off.Enabled)
	}
	on, err := m.Toggle(ctx, mon.ID, true)
	if err != nil || !on.Enabled {
		t.Fatalf("toggle(true): %v (enabled=%v)", err, on.Enabled)
	}

	if _, err := m.Run(ctx, mon.ID); err != nil {
		t.Fatalf("run: %v", err)
	}
	five := 5
	if _, err := m.Changes(ctx, mon.ID, &CloudChangeListOptions{Limit: &five}); err != nil {
		t.Fatalf("changes: %v", err)
	}
	if _, err := m.RecentChanges(ctx, &CloudChangeListOptions{Limit: &five}); err != nil {
		t.Fatalf("recent changes: %v", err)
	}

	// The plan floor is ENFORCED, not clamped: a sub-floor interval must surface
	// as an error, never as a quietly slowed-down monitor.
	tooFast := int64(1000)
	if _, err := m.Create(ctx, CloudMonitorParams{URL: seed, CheckPeriodMs: &tooFast}); err == nil {
		t.Error("a sub-floor check_period_ms was accepted; it must be rejected")
	} else {
		// It is a PLAN CEILING, not a wallet balance: mapping it to
		// InsufficientCredits would send the caller to top up for nothing.
		var planErr *PlanLimitError
		if !errors.As(err, &planErr) {
			t.Errorf("sub-floor error = %T (%v), want *PlanLimitError", err, err)
		} else if planErr.Code != "interval_too_short" || planErr.Limit == 0 {
			t.Errorf("plan error lost its structure: %+v", planErr)
		}
	}

	if err := m.Delete(ctx, mon.ID); err != nil {
		t.Fatalf("delete: %v", err)
	}
	after, err := m.List(ctx, &CloudMonitorListOptions{Limit: &limit})
	if err != nil {
		t.Fatalf("list after delete: %v", err)
	}
	if containsMonitor(after, mon.ID) {
		t.Error("the monitor is still listed after delete")
	}

	depth, budget := int64(0), int64(1)
	job, err := c.Cloud.Crawl(ctx, CrawlStartParams{URL: seed, MaxDepth: &depth, PageBudget: &budget})
	if err != nil {
		t.Fatalf("crawl: %v", err)
	}
	status, err := c.Cloud.CrawlStatus(ctx, job.ID)
	if err != nil {
		t.Fatalf("crawl status: %v", err)
	}
	if status.SeedURL == "" {
		t.Errorf("crawl status carried no seed_url: %+v", status)
	}
}

func containsMonitor(rows []CloudMonitor, id int64) bool {
	for _, r := range rows {
		if r.ID == id {
			return true
		}
	}
	return false
}

func envOr(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
}

/**
 * Env-gated LIVE test: drives `client.cloud.monitors` and `client.cloud.crawl`
 * against a REAL running coordinator. No mocks — this is the test that would
 * have caught a wrong path, a wrong casing or a scope the route map never mapped.
 *
 * ```sh
 * WRIT_E2E=1 WRIT_CLOUD_URL=http://localhost:8000 WRIT_API_KEY=wt_… npx vitest run test/cloud-monitors-live.test.ts
 * ```
 *
 * The key needs monitors:read/write/execute/delete and crawl:read/execute.
 * Skipped (not failed) when WRIT_E2E is unset, so `npm test` stays hermetic.
 */
import { afterAll, describe, expect, it } from "vitest";
import { CloudApi, WritApiError } from "../src/index.js";

const LIVE = process.env["WRIT_E2E"] === "1";
/** Each of these makes ~10 sequential round-trips against a REAL coordinator.
 *  Vitest's 5s default made the monitor lifecycle flaky at ~9s — this is a
 *  network budget, not a performance assertion. */
const LIVE_TIMEOUT_MS = 60_000;
const cloudUrl = process.env["WRIT_CLOUD_URL"] ?? "http://localhost:8000";
const apiKey = [REDACTED]"WRIT_API_KEY"] ?? "";

// example.com is the one URL guaranteed to exist and answer 200 — the API
// fetches the page to establish a baseline, so a 404 seed is rejected outright.
const SEED = "https://example.com";

describe.skipIf(!LIVE)("cloud monitors against a live coordinator", () => {
  const cloud = new CloudApi({ apiKey, cloudUrl });
  let created: number | undefined;

  afterAll(async () => {
    // Never leave a monitor behind, even if an expectation blew up mid-test.
    if (created !== undefined) {
      await cloud.monitors.delete(created).catch(() => undefined);
    }
  });

  it("runs the full monitor lifecycle", async () => {
    expect(cloud.tier).toBe("metered");

    const mon = await cloud.monitors.create({
      url: SEED,
      check_type: "content",
      selector: "h1",
      check_period_ms: 300_000,
    });
    created = mon.id;
    // The types in cloud.ts claim camelCase — assert the server agrees.
    expect(mon.checkPeriodMs).toBe(300_000);
    expect(mon.selector).toBe("h1");
    expect(mon.enabled).toBe(true);

    const listed = await cloud.monitors.list({ limit: 100 });
    expect(listed.some((m) => m.id === created)).toBe(true);

    const got = await cloud.monitors.get(mon.id);
    expect(got.url).toBe(SEED);

    const updated = await cloud.monitors.update(mon.id, { check_period_ms: 600_000 });
    expect(updated.checkPeriodMs).toBe(600_000);

    expect((await cloud.monitors.toggle(mon.id, false)).enabled).toBe(false);
    expect((await cloud.monitors.toggle(mon.id, true)).enabled).toBe(true);

    const run = await cloud.monitors.run(mon.id);
    expect(typeof run.ok).toBe("boolean");
    expect(typeof run.dispatched).toBe("number");

    expect(Array.isArray(await cloud.monitors.changes(mon.id, { limit: 5 }))).toBe(true);
    expect(Array.isArray(await cloud.monitors.recentChanges({ limit: 5 }))).toBe(true);

    await cloud.monitors.delete(mon.id);
    const after = await cloud.monitors.list({ limit: 100 });
    expect(after.some((m) => m.id === created)).toBe(false);
    created = undefined;
  }, LIVE_TIMEOUT_MS);

  it("surfaces the plan interval floor as an error instead of clamping", async () => {
    // plan_enforcer REJECTS a sub-floor interval; it must not come back as a
    // quietly slowed-down monitor the caller never asked for.
    await expect(cloud.monitors.create({ url: SEED, check_period_ms: 1000 })).rejects.toBeInstanceOf(
      WritApiError,
    );
  }, LIVE_TIMEOUT_MS);

  it("starts and polls a real crawl", async () => {
    const job = await cloud.crawl({ url: SEED, max_depth: 0, page_budget: 1 });
    expect(typeof job.id).toBe("number");
    const status = await cloud.crawlStatus(job.id);
    expect(status.seed_url).toContain("example.com");
  });
});

